// flow arrows (×2) → CylinderGeometry(0.025,0.025,len) + ConeGeometry(0.06,0.15) black #111
// caption box → HTML overlay div, cream background
// labels → addLabel for n, Area ΔS_k, Surface σ_k

const SURF_F = (x, y) => 0.12 * (x * x - y * y);
const SURF_FX = (x) => 0.24 * x;
const SURF_FY = (y) => -0.24 * y;

let patchU = 0, patchV = 0;
let flowSpeed = 1;
const PATCH_HALF = 0.45;
const PATCH_THICK = 0.18;

// ── Full surface ──
const surfGeom = new THREE.PlaneGeometry(4, 4, 48, 48);
surfGeom.rotateX(-Math.PI / 2);
const surfPos = surfGeom.attributes.position;
for (let i = 0; i < surfPos.count; i++) {
  const x = surfPos.getX(i), z = surfPos.getZ(i);
  surfPos.setY(i, SURF_F(x, z));
}
surfGeom.computeVertexNormals();
const surfMat = new THREE.MeshBasicMaterial({
  color: 0x8fd8c6, transparent: true, opacity: 0.35, side: THREE.DoubleSide
});
const surfMesh = new THREE.Mesh(surfGeom, surfMat);
scene.add(surfMesh);

// Surface edge lines
const surfEdgeMat = new THREE.LineBasicMaterial({ color: 0x16a89a });
const surfEdges = new THREE.EdgesGeometry(surfGeom);
const surfEdgeLines = new THREE.LineSegments(surfEdges, surfEdgeMat);
scene.add(surfEdgeLines);

// ── Patch group ──
const patchGroup = new THREE.Group();
scene.add(patchGroup);

function buildPatchGeometry() {
  // Top face
  const topGeom = new THREE.PlaneGeometry(PATCH_HALF * 2, PATCH_HALF * 2, 12, 12);
  topGeom.rotateX(-Math.PI / 2);
  const tp = topGeom.attributes.position;
  for (let i = 0; i < tp.count; i++) {
    const x = tp.getX(i) + patchU, z = tp.getZ(i) + patchV;
    tp.setY(i, SURF_F(x, z));
  }
  tp.needsUpdate = true;
  topGeom.computeVertexNormals();
  return topGeom;
}

const patchTopMat = new THREE.MeshBasicMaterial({ color: 0x7fd4c1, side: THREE.DoubleSide });
const patchTopMesh = new THREE.Mesh(buildPatchGeometry(), patchTopMat);
patchGroup.add(patchTopMesh);

// Patch edges (top face border)
const patchEdgeMat = new THREE.LineBasicMaterial({ color: 0x16a89a });
let patchEdgeLines = new THREE.LineSegments(new THREE.EdgesGeometry(patchTopMesh.geometry), patchEdgeMat);
patchGroup.add(patchEdgeLines);

// Bottom face
const patchBotMat = new THREE.MeshBasicMaterial({ color: 0x5cc4b0, side: THREE.DoubleSide });
let patchBotMesh = new THREE.Mesh(patchTopMesh.geometry.clone(), patchBotMat);
patchBotMesh.position.y = -PATCH_THICK;
patchGroup.add(patchBotMesh);

// Side faces (4 quads)
const sideMat = new THREE.MeshBasicMaterial({ color: 0x5cc4b0, side: THREE.DoubleSide });
let sideMeshes = [];
function buildSideFaces() {
  sideMeshes.forEach(m => { patchGroup.remove(m); m.geometry.dispose(); });
  sideMeshes = [];
  const tp = patchTopMesh.geometry.attributes.position;
  const n = 13; // 12+1 vertices per edge
  const edges = [
    // front edge (z = patchV - PATCH_HALF): indices row 0
    Array.from({length: n}, (_, i) => i),
    // back edge (z = patchV + PATCH_HALF): last row
    Array.from({length: n}, (_, i) => (n-1)*n + i),
    // left edge (x = patchU - PATCH_HALF): first column
    Array.from({length: n}, (_, i) => i * n),
    // right edge (x = patchU + PATCH_HALF): last column
    Array.from({length: n}, (_, i) => i * n + (n-1)),
  ];
  for (const edgeIdx of edges) {
    const pts = [];
    for (const idx of edgeIdx) {
      const x = tp.getX(idx), y = tp.getY(idx), z = tp.getZ(idx);
      pts.push(new THREE.Vector3(x, y, z));
      pts.push(new THREE.Vector3(x, y - PATCH_THICK, z));
    }
    const geom = new THREE.BufferGeometry();
    const verts = [];
    for (let i = 0; i < edgeIdx.length - 1; i++) {
      const a = pts[i*2], b = pts[i*2+1], c = pts[(i+1)*2], dd = pts[(i+1)*2+1];
      verts.push(a.x,a.y,a.z, c.x,c.y,c.z, b.x,b.y,b.z);
      verts.push(b.x,b.y,b.z, c.x,c.y,c.z, dd.x,dd.y,dd.z);
    }
    geom.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
    geom.computeVertexNormals();
    const mesh = new THREE.Mesh(geom, sideMat);
    patchGroup.add(mesh);
    sideMeshes.push(mesh);
  }
}
buildSideFaces();

// Dashed hidden back edges
const dashMat = new THREE.LineDashedMaterial({ color: 0x16a89a, dashSize: 0.08, gapSize: 0.05 });
let hiddenEdgeLines = null;
function buildHiddenEdges() {
  if (hiddenEdgeLines) { patchGroup.remove(hiddenEdgeLines); hiddenEdgeLines.geometry.dispose(); }
  const tp = patchTopMesh.geometry.attributes.position;
  const n = 13;
  const backEdge = Array.from({length: n}, (_, i) => (n-1)*n + i);
  const leftEdge = Array.from({length: n}, (_, i) => i * n);
  const pts = [];
  for (const idx of backEdge) {
    pts.push(new THREE.Vector3(tp.getX(idx), tp.getY(idx), tp.getZ(idx)));
  }
  for (const idx of leftEdge) {
    pts.push(new THREE.Vector3(tp.getX(idx), tp.getY(idx), tp.getZ(idx)));
  }
  const geom = new THREE.BufferGeometry().setFromPoints(pts);
  hiddenEdgeLines = new THREE.Line(geom, dashMat);
  hiddenEdgeLines.computeLineDistances();
  patchGroup.add(hiddenEdgeLines);
}
buildHiddenEdges();

// ── Normal arrow ──
const normalGroup = new THREE.Group();
scene.add(normalGroup);

const shaftMat = new THREE.MeshBasicMaterial({ color: 0xb04fb0 });
const shaftGeom = new THREE.CylinderGeometry(0.02, 0.02, 0.7, 8);
const shaftMesh = new THREE.Mesh(shaftGeom, shaftMat);
normalGroup.add(shaftMesh);

// Open triangular head (wireframe cone)
const headMat = new THREE.MeshBasicMaterial({ color: 0xb04fb0, wireframe: false, side: THREE.DoubleSide });
const headGeom = new THREE.ConeGeometry(0.06, 0.15, 4);
const headMesh = new THREE.Mesh(headGeom, headMat);
headMesh.position.y = 0.7 / 2 + 0.075;
normalGroup.add(headMesh);

// Make head "open" - use edges
const headEdgeMat = new THREE.LineBasicMaterial({ color: 0xb04fb0 });
const headEdges = new THREE.LineSegments(new THREE.EdgesGeometry(headGeom), headEdgeMat);
headEdges.position.copy(headMesh.position);
normalGroup.add(headEdges);
headMesh.material = new THREE.MeshBasicMaterial({ color: 0xb04fb0, transparent: true, opacity: 0.3, side: THREE.DoubleSide });

// ── Sample dot ──
const dotGeom = new THREE.SphereGeometry(0.04, 12, 12);
const dotMat = new THREE.MeshBasicMaterial({ color: 0x16a89a });
const dotMesh = new THREE.Mesh(dotGeom, dotMat);
scene.add(dotMesh);

// ── Flow arrows ──
const flowArrowMat = new THREE.MeshBasicMaterial({ color: 0x111111 });
const flowArrows = [];
function createFlowArrow() {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 0.5, 8), flowArrowMat);
  shaft.position.y = 0.25;
  g.add(shaft);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.15, 8), flowArrowMat);
  head.position.y = 0.5 + 0.075;
  g.add(head);
  scene.add(g);
  flowArrows.push(g);
  return g;
}
const flowArrowL = createFlowArrow();
const flowArrowR = createFlowArrow();

// ── Update function ──
function getNormal(u, v) {
  const fx = SURF_FX(u), fy = SURF_FY(v);
  const n = new THREE.Vector3(-fx, -fy, 1).normalize();
  return n;
}

function getDeltaSk(u, v) {
  const fx = SURF_FX(u), fy = SURF_FY(v);
  const flatArea = (PATCH_HALF * 2) * (PATCH_HALF * 2);
  return flatArea * Math.sqrt(1 + fx * fx + fy * fy);
}

function updatePatch() {
  // Rebuild top face
  const newTopGeom = buildPatchGeometry();
  const oldGeom = patchTopMesh.geometry;
  patchTopMesh.geometry = newTopGeom;
  oldGeom.dispose();

  // Update edges
  patchGroup.remove(patchEdgeLines);
  patchEdgeLines.geometry.dispose();
  patchEdgeLines = new THREE.LineSegments(new THREE.EdgesGeometry(newTopGeom), patchEdgeMat);
  patchGroup.add(patchEdgeLines);

  // Update bottom face
  patchGroup.remove(patchBotMesh);
  patchBotMesh.geometry.dispose();
  patchBotMesh = new THREE.Mesh(newTopGeom.clone(), patchBotMat);
  patchBotMesh.position.y = -PATCH_THICK;
  patchGroup.add(patchBotMesh);

  // Rebuild sides and hidden edges
  buildSideFaces();
  buildHiddenEdges();

  // Update normal arrow
  const n = getNormal(patchU, patchV);
  const centerPos = new THREE.Vector3(patchU, SURF_F(patchU, patchV), patchV);
  normalGroup.position.copy(centerPos);
  normalGroup.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), n);

  // Update dot
  dotMesh.position.copy(centerPos);

  // Update flow arrows
  const arrowLen = 0.3 + flowSpeed * 0.15;
  const leftPos = new THREE.Vector3(patchU - PATCH_HALF - 0.3, SURF_F(patchU - PATCH_HALF - 0.3, patchV), patchV);
  const rightPos = new THREE.Vector3(patchU + PATCH_HALF + 0.3, SURF_F(patchU + PATCH_HALF + 0.3, patchV), patchV);

  flowArrowL.position.copy(leftPos);
  flowArrowR.position.copy(rightPos);

  // Scale arrows with velocity
  const s = 0.5 + flowSpeed * 0.3;
  flowArrowL.scale.set(1, s, 1);
  flowArrowR.scale.set(1, s, 1);

  // Update flux readout
  const dSk = getDeltaSk(patchU, patchV);
  const nz = n.z;
  const flux = flowSpeed * nz * dSk;
  document.getElementById('fluxVal').textContent = flux.toFixed(3);
}

updatePatch();

// ── Labels ──
addLabel('<b>n</b>', new THREE.Vector3(patchU, SURF_F(patchU, patchV) + 0.85, patchV), { offset: [15, -10], fontSize: '15px' });
const areaLabelPos = new THREE.Vector3(patchU + PATCH_HALF * 0.5, SURF_F(patchU, patchV) + 0.3, patchV - PATCH_HALF * 0.5);
