Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Flow speed |F|
  <input type="range" id="velocity" min="0" max="5" step="0.1" value="1">
  <span id="velVal">1.0</span>
</label>
<div id="fluxReadout" style="font-size:12px;margin-top:4px;">Flux = <b id="fluxVal">0.00</b></div>
<button id="btnStep1">Step 1: Patch flat (max flux)</button>
<button id="btnStep2">Step 2: Tilt patch 45°</button>
<button id="btnStep3">Step 3: Raise flow speed</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// patch top face → PlaneGeometry(2.4,1.8,16,16) deformed y=h*(1-0.5*(x/a)²-0.5*(z/b)²), teal #7fd4c1
// patch bottom face → same offset -0.35 in y, darker #5cc4b0
// patch side faces → 4 strips connecting top/bottom edges, #5cc4b0
// patch top edges → LineSegments teal #16a89a
// hidden back edges → dashed LineSegments #16a89a
// normal arrow shaft → CylinderGeometry(0.025,0.025,0.8) magenta #b04fb0
// normal arrow head → ConeGeometry(0.07,0.18,4) semi-transparent magenta
// sample dot → SphereGeometry(0.05) teal #16a89a
// flow arrows (×2) → CylinderGeometry(0.03,0.03,0.5)+ConeGeometry(0.07,0.18) black #111
// caption box → HTML overlay div, cream background
// labels → addLabel for n, Area ΔS_k, Surface σ_k

const PATCH_A = 1.2;   // half-width in x
const PATCH_B = 0.9;   // half-depth in z
const PATCH_H = 0.25;  // dome height at center
const PATCH_THICK = 0.35;

let tiltAngle = 0;     // radians, tilt around x-axis
let flowSpeed = 1;

function domeY(x, z) {
  return PATCH_H * (1 - 0.5 * (x / PATCH_A) * (x / PATCH_A) - 0.5 * (z / PATCH_B) * (z / PATCH_B));
}

// ── Patch group ──
const patchGroup = new THREE.Group();
scene.add(patchGroup);

function buildTopGeometry() {
  const geom = new THREE.PlaneGeometry(PATCH_A * 2, PATCH_B * 2, 16, 16);
  geom.rotateX(-Math.PI / 2);
  const pos = geom.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), z = pos.getZ(i);
    pos.setY(i, domeY(x, z));
  }
  pos.needsUpdate = true;
  geom.computeVertexNormals();
  return geom;
}

const patchTopMat = new THREE.MeshBasicMaterial({ color: 0x7fd4c1, side: THREE.DoubleSide });
const patchTopMesh = new THREE.Mesh(buildTopGeometry(), patchTopMat);
patchGroup.add(patchTopMesh);

// Top face edges
const patchEdgeMat = new THREE.LineBasicMaterial({ color: 0x16a89a });
let patchEdgeLines = new THREE.LineSegments(new THREE.EdgesGeometry(patchTopMesh.geometry), patchEdgeMat);
patchGroup.add(patchEdgeLines);

// Bottom face
const patchBotMat = new THREE.MeshBasicMaterial({ color: 0x5cc4b0, side: THREE.DoubleSide });
let patchBotMesh = new THREE.Mesh(patchTopMesh.geometry.clone(), patchBotMat);
patchBotMesh.position.y = -PATCH_THICK;
patchGroup.add(patchBotMesh);

// Side faces
const sideMat = new THREE.MeshBasicMaterial({ color: 0x5cc4b0, side: THREE.DoubleSide });
let sideMeshes = [];

function buildSideFaces() {
  sideMeshes.forEach(m => { patchGroup.remove(m); m.geometry.dispose(); });
  sideMeshes = [];
  const tp = patchTopMesh.geometry.attributes.position;
  const n = 17; // 16+1 vertices per edge
  const edges = [
    Array.from({ length: n }, (_, i) => i),                    // front (z=-B)
    Array.from({ length: n }, (_, i) => (n - 1) * n + i),      // back (z=+B)
    Array.from({ length: n }, (_, i) => i * n),                // left (x=-A)
    Array.from({ length: n }, (_, i) => i * n + (n - 1)),      // right (x=+A)
  ];
  for (const edgeIdx of edges) {
    const verts = [];
    for (let i = 0; i < edgeIdx.length - 1; i++) {
      const i0 = edgeIdx[i], i1 = edgeIdx[i + 1];
      const ax = tp.getX(i0), ay = tp.getY(i0), az = tp.getZ(i0);
      const bx = tp.getX(i1), by = tp.getY(i1), bz = tp.getZ(i1);
      // quad: top0, top1, bot0, bot1
      verts.push(ax, ay, az, bx, by, bz, ax, ay - PATCH_THICK, az);
      verts.push(ax, ay - PATCH_THICK, az, bx, by, bz, bx, by - PATCH_THICK, bz);
    }
    const geom = new THREE.BufferGeometry();
    geom.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
    geom.computeVertexNormals();
    const mesh = new THREE.Mesh(geom, sideMat);
    patchGroup.add(mesh);
    sideMeshes.push(mesh);
  }
}
buildSideFaces();

// Hidden back edges (dashed)
const dashMat = new THREE.LineDashedMaterial({ color: 0x16a89a, dashSize: 0.1, gapSize: 0.06 });
let hiddenEdgeLines = null;

function buildHiddenEdges() {
  if (hiddenEdgeLines) { patchGroup.remove(hiddenEdgeLines); hiddenEdgeLines.geometry.dispose(); }
  const tp = patchTopMesh.geometry.attributes.position;
  const n = 17;
  const backEdge = Array.from({ length: n }, (_, i) => (n - 1) * n + i);
  const leftEdge = Array.from({ length: n }, (_, i) => i * n);
  const pts = [];
  for (const idx of backEdge) pts.push(new THREE.Vector3(tp.getX(idx), tp.getY(idx), tp.getZ(idx)));
  for (const idx of leftEdge) pts.push(new THREE.Vector3(tp.getX(idx), tp.getY(idx), tp.getZ(idx)));
  const geom = new THREE.BufferGeometry().setFromPoints(pts);
  hiddenEdgeLines = new THREE.Line(geom, dashMat);
  hiddenEdgeLines.computeLineDistances();
  patchGroup.add(hiddenEdgeLines);
}
buildHiddenEdges();

// ── Normal arrow ──
const normalGroup = new THREE.Group();
patchGroup.add(normalGroup);

const shaftMat = new THREE.MeshBasicMaterial({ color: 0xb04fb0 });
const shaftMesh = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 0.8, 8), shaftMat);
shaftMesh.position.y = 0.4;
normalGroup.add(shaftMesh);

const headMat = new THREE.MeshBasicMaterial({ color: 0xb04fb0, transparent: true, opacity: 0.4, side: THREE.DoubleSide });
const headMesh = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.18, 4), headMat);
headMesh.position.y = 0.8 + 0.09;
normalGroup.add(headMesh);

const headEdgeMat = new THREE.LineBasicMaterial({ color: 0xb04fb0 });
const headEdges = new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.ConeGeometry(0.07, 0.18, 4)), headEdgeMat);
headEdges.position.copy(headMesh.position);
normalGroup.add(headEdges);

// Position normal group at dome center
normalGroup.position.set(0, domeY(0, 0), 0);

// ── Sample dot ──
const dotMesh = new THREE.Mesh(new THREE.SphereGeometry(0.05, 12, 12), new THREE.MeshBasicMaterial({ color: 0x16a89a }));
dotMesh.position.set(0, domeY(0, 0), 0);
patchGroup.add(dotMesh);

// ── Flow arrows ──
const flowArrowMat = new THREE.MeshBasicMaterial({ color: 0x111111 });
function createFlowArrow(x, z) {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 0.5, 8), flowArrowMat);
  shaft.position.y = 0.25;
  g.add(shaft);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.18, 8), flowArrowMat);
  head.position.y = 0.5 + 0.09;
  g.add(head);
  g.position.set(x, domeY(x, z) - 0.1, z);
  patchGroup.add(g);
  return g;
}
const flowArrowL = createFlowArrow(-PATCH_A - 0.35, 0);
const flowArrowR = createFlowArrow(PATCH_A + 0.35, 0);

// ── Update ──
function getNormal() {
  // Normal of the tilted patch: rotate (0,1,0) by tiltAngle around x
  return new THREE.Vector3(0, Math.cos(tiltAngle), Math.sin(tiltAngle));
}

function updateScene() {
  patchGroup.rotation.x = tiltAngle;

  const n = getNormal();
  const flux = flowSpeed * n.y * (PATCH_A * 2) * (PATCH_B * 2);
  document.getElementById('fluxVal').textContent = flux.toFixed(3);

  // Scale flow arrows with speed
  const s = 0.5 + flowSpeed * 0.25;
  flowArrowL.scale.set(1, s, 1);
  flowArrowR.scale.set(1, s, 1);
}
updateScene();

// ── Labels ──
addLabel('<b>n</b>', new THREE.Vector3(0.15, domeY(0, 0) + 1.05, 0), { offset: [12, -8], fontSize: '15px' });
addLabel('Area Δ<i>S</i><sub><i>k</i></sub>', new THREE.Vector3(PATCH_A * 0.6, domeY(PATCH_A * 0.6, 0) + 0.5, -PATCH_B * 0.3), { offset: [55, -25], fontSize: '13px' });
addLabel('Surface σ<sub><i>k</i></sub>', new THREE.Vector3(PATCH_A + 0.3, domeY(PATCH_A, 0) - 0.15, PATCH_B * 0.4), { offset: [60, 8], fontSize: '13px' });

// ── Caption box ──
const captionDiv = document.createElement('div');
captionDiv.style.cssText = `
  position: absolute; bottom: 10px; left: 50%; transform: translateX(-50%);
  background: #f7e3b0; border: 2px solid #9a9a9a; border-radius: 6px;
  padding: 10px 14px; font: 12px/1.4 sans-serif; color: #111;
  max-width: 260px; pointer-events: none; z-index: 5;
`;
captionDiv.innerHTML = 'The volume of fluid crossing σ<sub><i>k</i></sub> in the direction of <b>n</b> per unit of time.';
_stage.appendChild(captionDiv);

// ── Drag to tilt ──
let isDragging = false;
let dragStartY = 0;
let dragStartTilt = 0;

canvas.addEventListener('pointerdown', (e) => {
  const rect = canvas.getBoundingClientRect();
  const px = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  const py = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  const rc = new THREE.Raycaster();
  rc.setFromCamera(new THREE.Vector2(px, py), camera);
  const hits = rc.intersectObject(patchTopMesh);
  if (hits.length > 0) {
    isDragging = true;
    dragStartY = e.clientY;
    dragStartTilt = tiltAngle;
    controls.enabled = false;
    e.stopPropagation();
  }
});

canvas.addEventListener('pointermove', (e) => {
  if (!isDragging) return;
  const dy = e.clientY - dragStartY;
  tiltAngle = THREE.MathUtils.clamp(dragStartTilt + dy * 0.005, -Math.PI / 3, Math.PI / 3);
  updateScene();
});

canvas.addEventListener('pointerup', () => {
  isDragging = false;
  controls.enabled = true;
});

// ── Velocity slider ──
const velSlider = document.getElementById('velocity');
velSlider.addEventListener('input', () => {
  flowSpeed = parseFloat(velSlider.value);
  document.getElementById('velVal').textContent = flowSpeed.toFixed(1);
  updateScene();
});

// ── Steps ──
document.getElementById('btnStep1').addEventListener('click', () => {
  tiltAngle = 0; flowSpeed = 1;
  velSlider.value = 1;
  document.getElementById('velVal').textContent = '1.0';
  updateScene();
});
document.getElementById('btnStep2').addEventListener('click', () => {
  tiltAngle = Math.PI / 4; flowSpeed = 1;
  velSlider.value = 1;
  document.getElementById('velVal').textContent = '1.0';
  updateScene();
});
document.getElementById('btnStep3').addEventListener('click', () => {
  tiltAngle = Math.PI / 4; flowSpeed = 4;
  velSlider.value = 4;
