const PATCH_A = 1.2;
const PATCH_B = 0.9;
const PATCH_H = 0.25;
const PATCH_THICK = 0.35;

let tiltAngle = 0;
let flowSpeed = 1;

function domeY(x, z) {
  return PATCH_H * (1 - 0.5 * (x / PATCH_A) * (x / PATCH_A) - 0.5 * (z / PATCH_B) * (z / PATCH_B));
}

const patchGroup = new THREE.Group();
scene.add(patchGroup);

function buildTopGeometry() {
  const geom = new THREE.PlaneGeometry(PATCH_A * 2, PATCH_B * 2, 16, 16);
  geom.rotateX(-Math.PI / 2);
  const pos = geom.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), z = pos.getZ(i);
    pos.setY(i, domeY(x, z));
  }
  pos.needsUpdate = true;
  geom.computeVertexNormals();
  return geom;
}

const patchTopMat = new THREE.MeshBasicMaterial({ color: 0x7fd4c1, side: THREE.DoubleSide });
const patchTopMesh = new THREE.Mesh(buildTopGeometry(), patchTopMat);
patchGroup.add(patchTopMesh);

// Border edges only (no internal grid)
function buildBorderEdges() {
  const tp = patchTopMesh.geometry.attributes.position;
  const n = 17;
  const pts = [];
  // front edge (z = -B, row 0)
  for (let i = 0; i < n - 1; i++) {
    pts.push(new THREE.Vector3(tp.getX(i), tp.getY(i), tp.getZ(i)));
    pts.push(new THREE.Vector3(tp.getX(i + 1), tp.getY(i + 1), tp.getZ(i + 1)));
  }
  // back edge (z = +B, row n-1)
  const backStart = (n - 1) * n;
  for (let i = 0; i < n - 1; i++) {
    pts.push(new THREE.Vector3(tp.getX(backStart + i), tp.getY(backStart + i), tp.getZ(backStart + i)));
    pts.push(new THREE.Vector3(tp.getX(backStart + i + 1), tp.getY(backStart + i + 1), tp.getZ(backStart + i + 1)));
  }
  // left edge (x = -A, col 0)
  for (let i = 0; i < n - 1; i++) {
    const i0 = i * n, i1 = (i + 1) * n;
    pts.push(new THREE.Vector3(tp.getX(i0), tp.getY(i0), tp.getZ(i0)));
    pts.push(new THREE.Vector3(tp.getX(i1), tp.getY(i1), tp.getZ(i1)));
  }
  // right edge (x = +A, col n-1)
  for (let i = 0; i < n - 1; i++) {
    const i0 = i * n + (n - 1), i1 = (i + 1) * n + (n - 1);
    pts.push(new THREE.Vector3(tp.getX(i0), tp.getY(i0), tp.getZ(i0)));
    pts.push(new THREE.Vector3(tp.getX(i1), tp.getY(i1), tp.getZ(i1)));
  }
  return new THREE.BufferGeometry().setFromPoints(pts);
}

const patchEdgeMat = new THREE.LineBasicMaterial({ color: 0x16a89a });
const patchEdgeLines = new THREE.LineSegments(buildBorderEdges(), patchEdgeMat);
patchGroup.add(patchEdgeLines);

// Bottom face
const patchBotMat = new THREE.MeshBasicMaterial({ color: 0x5cc4b0, side: THREE.DoubleSide });
const patchBotMesh = new THREE.Mesh(patchTopMesh.geometry.clone(), patchBotMat);
patchBotMesh.position.y = -PATCH_THICK;
patchGroup.add(patchBotMesh);

// Side faces
const sideMat = new THREE.MeshBasicMaterial({ color: 0x5cc4b0, side: THREE.DoubleSide });
const sideMeshes = [];

function buildSideFaces() {
  const tp = patchTopMesh.geometry.attributes.position;
  const n = 17;
  const edges = [
    Array.from({ length: n }, (_, i) => i),
    Array.from({ length: n }, (_, i) => (n - 1) * n + i),
    Array.from({ length: n }, (_, i) => i * n),
    Array.from({ length: n }, (_, i) => i * n + (n - 1)),
  ];
  for (const edgeIdx of edges) {
    const verts = [];
    for (let i = 0; i < edgeIdx.length - 1; i++) {
      const i0 = edgeIdx[i], i1 = edgeIdx[i + 1];
      const ax = tp.getX(i0), ay = tp.getY(i0), az = tp.getZ(i0);
      const bx = tp.getX(i1), by = tp.getY(i1), bz = tp.getZ(i1);
      verts.push(ax, ay, az, bx, by, bz, ax, ay - PATCH_THICK, az);
      verts.push(ax, ay - PATCH_THICK, az, bx, by, bz, bx, by - PATCH_THICK, bz);
    }
    const geom = new THREE.BufferGeometry();
    geom.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
    geom.computeVertexNormals();
    const mesh = new THREE.Mesh(geom, sideMat);
    patchGroup.add(mesh);
    sideMeshes.push(mesh);
  }
}
buildSideFaces();

// Hidden back edges (dashed)
const dashMat = new THREE.LineDashedMaterial({ color: 0x16a89a, dashSize: 0.1, gapSize: 0.06 });
function buildHiddenEdges() {
  const tp = patchTopMesh.geometry.attributes.position;
  const n = 17;
  const backEdge = Array.from({ length: n }, (_, i) => (n - 1) * n + i);
  const leftEdge = Array.from({ length: n }, (_, i) => i * n);
  const pts = [];
  for (const idx of backEdge) pts.push(new THREE.Vector3(tp.getX(idx), tp.getY(idx), tp.getZ(idx)));
  for (const idx of leftEdge) pts.push(new THREE.Vector3(tp.getX(idx), tp.getY(idx), tp.getZ(idx)));
  const geom = new THREE.BufferGeometry().setFromPoints(pts);
  const line = new THREE.Line(geom, dashMat);
  line.computeLineDistances();
  patchGroup.add(line);
}
buildHiddenEdges();

// ── Normal arrow with OPEN/HOLLOW triangle arrowhead ──
const normalGroup = new THREE.Group();
patchGroup.add(normalGroup);

const shaftMat = new THREE.MeshBasicMaterial({ color: 0xb04fb0 });
const shaftMesh = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 0.8, 8), shaftMat);
