// ── Flow arrows ──
const flowArrowMat = new THREE.MeshBasicMaterial({ color: 0x111111 });
function createFlowArrow(x, z) {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 0.5, 8), flowArrowMat);
  shaft.position.y = 0.25;
  g.add(shaft);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.18, 8), flowArrowMat);
  head.position.y = 0.5 + 0.09;
  g.add(head);
  g.position.set(x, domeY(x, z) - 0.1, z);
  patchGroup.add(g);
  return g;
}
const flowArrowL = createFlowArrow(-PATCH_A - 0.35, 0);
const flowArrowR = createFlowArrow(PATCH_A + 0.35, 0);

// ── Curved annotation arrows ──
function createCurvedArrow(start, control, end, color = 0x111111) {
  const curve = new THREE.QuadraticBezierCurve3(start, control, end);
  const points = curve.getPoints(30);
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = new THREE.LineBasicMaterial({ color });
  const line = new THREE.Line(geom, mat);
  patchGroup.add(line);

  // Arrowhead at end
  const dir = new THREE.Vector3().subVectors(end, points[points.length - 2]).normalize();
  const headLen = 0.1;
  const headAngle = 0.5;
  const perp = new THREE.Vector3(0, 1, 0).cross(dir).normalize();
  if (perp.length() < 0.01) perp.set(1, 0, 0);
  const p1 = end.clone().add(dir.clone().multiplyScalar(-headLen)).add(perp.clone().multiplyScalar(headLen * Math.tan(headAngle)));
  const p2 = end.clone().add(dir.clone().multiplyScalar(-headLen)).add(perp.clone().multiplyScalar(-headLen * Math.tan(headAngle)));
  const headPts = [p1, end, p2];
  const headGeom = new THREE.BufferGeometry().setFromPoints(headPts);
  const headLine = new THREE.Line(headGeom, mat);
  patchGroup.add(headLine);
}

// Arrow from "Area ΔS_k" label pointing to top surface
createCurvedArrow(
  new THREE.Vector3(PATCH_A * 0.9, domeY(PATCH_A * 0.5, -PATCH_B * 0.3) + 0.7, -PATCH_B * 0.5),
  new THREE.Vector3(PATCH_A * 0.7, domeY(PATCH_A * 0.4, -PATCH_B * 0.2) + 0.45, -PATCH_B * 0.35),
