// Arrowhead on connector (pointing left/down toward caption)
const connEnd = connectorPts[3];
const connDir = new THREE.Vector3().subVectors(connEnd, connPoints[connPoints.length - 2]).normalize();
const connHeadLen = 0.15;
const connPerp = new THREE.Vector3(0, 0, 1).cross(connDir).normalize();
const cp1 = connEnd.clone().add(connDir.clone().multiplyScalar(-connHeadLen)).add(connPerp.clone().multiplyScalar(connHeadLen * 0.6));
const cp2 = connEnd.clone().add(connDir.clone().multiplyScalar(-connHeadLen)).add(connPerp.clone().multiplyScalar(-connHeadLen * 0.6));
const connHeadPts = [cp1, connEnd, cp2];
const connHeadGeom = new THREE.BufferGeometry().setFromPoints(connHeadPts);
const connHeadLine = new THREE.Line(connHeadGeom, connMat);
